/* محرر المناطق بالإعدادات */
function znSave(msg){ settings.zones.sort((a,b)=>a.cost-b.cost); saveAll(); zoneBuild(); znRender(); if(msg) toast(msg) }
function znRender(){
  const box=document.getElementById('znGroups'); if(!box) return;
  document.getElementById('znProfit').value=zProfit();
  document.getElementById('znFree').value=zFree();
  box.innerHTML=settings.zones.map((g,i)=>{
    const f=zoneFee(+g.cost||0);
    return `<div class="zn-g" data-i="${i}">
      <div class="zn-h">
        <label class="zn-cost"><span>كلفة السائق</span><input type="number" inputmode="numeric" min="0" step="250" value="${+g.cost||0}" data-act="cost" aria-label="كلفة السائق"></label>
        <span class="zn-pay ${f?'':'free'}">الزبون يدفع: <b>${f?fmt(f)+' د.ع':'مجاني'}</b></span>
        <button class="btn-sm zn-del" data-act="delg" aria-label="احذف المجموعة">حذف المجموعة</button>
      </div>
      <div class="zn-chips">${g.areas.map((a,j)=>`<span class="zn-chip">${esc(a)}<button data-act="dela" data-j="${j}" aria-label="احذف ${esc(a)}">×</button></span>`).join('')||'<span class="hint">ماكو مناطق بعد</span>'}</div>
      <div class="zn-add"><input placeholder="اسم منطقة جديدة" data-act="newa" aria-label="منطقة جديدة"><button class="btn-sm gold" data-act="adda">إضافة</button></div>
    </div>`;
  }).join('');
}
(function(){
  const box=document.getElementById('znGroups');
  const addArea=(i,inp)=>{
    const n=inp.value.trim().replace(/\s+/g,' '); if(!n) return;
    settings.zones.forEach(g=>{ g.areas=g.areas.filter(a=>a!==n) });   /* إذا موجودة بمجموعة ثانية تنتقل */
    settings.zones[i].areas.push(n); znSave('انضافت '+n);
  };
  box.addEventListener('click',e=>{
    const b=e.target.closest('[data-act]'); if(!b) return;
    const g=b.closest('.zn-g'), i=+g.dataset.i, act=b.dataset.act;
    if(act==='dela'){ const a=settings.zones[i].areas[+b.dataset.j]; if(!confirm('تحذف '+a+'؟')) return; settings.zones[i].areas.splice(+b.dataset.j,1); znSave('انحذفت '+a) }
    if(act==='delg'){ if(!confirm('تحذف المجموعة وكل مناطقها؟')) return; settings.zones.splice(i,1); znSave('انحذفت المجموعة') }
    if(act==='adda') addArea(i,g.querySelector('[data-act="newa"]'));
  });
  box.addEventListener('keydown',e=>{ if(e.key==='Enter'&&e.target.dataset.act==='newa'){ e.preventDefault(); addArea(+e.target.closest('.zn-g').dataset.i,e.target) } });
  box.addEventListener('change',e=>{
    if(e.target.dataset.act!=='cost') return;
    const i=+e.target.closest('.zn-g').dataset.i, v=Math.max(0,Math.round((+e.target.value||0)/250)*250);
    settings.zones[i].cost=v; znSave('انحفظ السعر');
  });
  document.getElementById('znAddGroup').addEventListener('click',()=>{
    const last=settings.zones.length?Math.max(...settings.zones.map(g=>+g.cost||0)):0;
    settings.zones.push({cost:last+1000,areas:[]}); znSave('انضافت مجموعة '+fmt(last+1000));
  });
  ['znProfit','znFree'].forEach(id=>document.getElementById(id).addEventListener('change',e=>{
    const v=Math.max(0,Math.round((+e.target.value||0)/250)*250);
    if(id==='znProfit') settings.zoneProfit=v; else settings.freeLimit=v;
    znSave('انحفظ');
  }));
  document.getElementById('znSearch').addEventListener('input',e=>{
    const q=e.target.value.trim();
    box.querySelectorAll('.zn-chip').forEach(c=>c.classList.toggle('hit',!!q&&c.textContent.includes(q)));
    const h=box.querySelector('.zn-chip.hit'); if(h) h.scrollIntoView({block:'nearest'});
  });
  znRender();
})();
