let ZONES={};
const zProfit=()=>+settings.zoneProfit||0, zFree=()=>+settings.freeLimit||0;
function zoneFee(cost){ const f=cost+zProfit(); return f<=zFree()?0:f }
function zoneBuild(){
  ZONES={};
  settings.zones.forEach(g=>g.areas.forEach(a=>{ ZONES[a]=+g.cost||0 }));
  const dl=document.getElementById('zoneList'); dl.innerHTML='';
/* ===== مناطق التوصيل (V95: تنعدل من الإعدادات) ===== */
const ZONE_DEF=[[2000,['الجزائر','العباسية','حي عمان','حي صنعاء','بريهة','الطويسة','المقاولين','الساعي','العشار','البراضعية','التحسينية','كوت الحجاج','حي الخضراء','الحكيمية','البصرة القديمة','صبخة العرب','حي الرافدين','السيمر']],
const SAFI_VER='V95';
    <div class="card" id="znCard">
      <h3>مناطق التوصيل والأسعار</h3>
      <p class="note" style="margin-bottom:12px">كل مجموعة إلها كلفة سائق وحدة. الي يدفعه الزبون = كلفة السائق + ربحنا، وإذا طلع أقل أو يساوي حد التوصيل المجاني يصير مجاني. أي تعديل هنا ينحفظ فوراً ويتغير بالكاشير.</p>
      <div class="zn-top">
        <div class="fld"><label for="znProfit">ربحنا على كل توصيلة (د.ع)</label><input id="znProfit" type="number" inputmode="numeric" min="0" step="250"></div>
        <div class="fld"><label for="znFree">مجاني إذا المجموع ما يعدي (د.ع)</label><input id="znFree" type="number" inputmode="numeric" min="0" step="250"></div>
      </div>
      <div class="fld"><label for="znSearch">دوّر على منطقة</label><input id="znSearch" placeholder="اكتب اسم المنطقة"></div>
      <div id="znGroups"></div>
      <button class="btn-sm" id="znAddGroup" style="width:100%;margin-top:12px">+ مجموعة سعر جديدة</button>
    </div>
.zn-top{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.zn-g{border:1px solid var(--line);border-radius:12px;padding:12px;margin-top:10px}
.zn-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.zn-cost{display:flex;align-items:center;gap:8px;font-size:14px}
.zn-cost input{width:110px;min-height:40px}
.zn-pay{font-size:14px}
.zn-pay b{color:var(--gold,#D4A24C)}
.zn-pay.free b{color:#3DDC84}
.zn-del{margin-inline-start:auto}
.zn-chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}
.zn-chip{display:inline-flex;align-items:center;gap:4px;border:1px solid var(--line2,var(--line));border-radius:999px;padding:2px 4px 2px 12px;font-size:14px}
.zn-chip.hit{background:#D4A24C;color:#111;border-color:#D4A24C}
.zn-chip button{width:30px;height:30px;border-radius:50%;background:none;border:0;color:inherit;font-size:18px;line-height:1;cursor:pointer}
.zn-add{display:flex;gap:8px}
.zn-add input{flex:1;min-height:40px}
